  "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Looking for ways to speed up your queries, or scale easily with your serverless or edge functions?\n// Try Prisma Accelerate: https://pris.ly/cli/accelerate-init\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = \"file:./local-app.db\"\n}\n\n// NextAuth models (simplified for local storage)\nmodel Account {\n  id                String  @id @default(cuid())\n  userId            String\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String?\n  access_token      String?\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String?\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n  user         User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel User {\n  id            String    @id @default(cuid())\n  name          String?\n  email         String?   @unique\n  emailVerified DateTime?\n  image         String?\n  accounts      Account[]\n  sessions      Session[]\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n}\n\n// Custom model to track email verification tokens\nmodel EmailVerificationRequest {\n  id          String   @id @default(cuid())\n  email       String\n  createdAt   DateTime @default(now())\n  invalidated Boolean  @default(false)\n\n  @@index([email])\n}\n\n// ===============================================\n// LOCAL DATA STORAGE MODELS\n// ===============================================\n\n// Local user preferences and profile\nmodel LocalUserProfile {\n  id                     String  @id @default(cuid())\n  userId                 String  @unique // Django user ID\n  publicId               String  @unique // Django public_id\n  email                  String\n  name                   String\n  hasCompletedOnboarding Boolean @default(false)\n\n  // Preferences\n  topics        String // JSON array of topic IDs\n  topicsDetails String? // JSON array of topic objects\n  regions       String // JSON array of region IDs  \n  languages     String // JSON array of language IDs\n  publications  String // JSON array of publication IDs\n\n  // Sync metadata\n  lastSyncAt DateTime @default(now())\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  // Related data\n  feedSyncs FeedSync[]\n\n  @@index([userId])\n  @@index([publicId])\n}\n\n// Local article storage\nmodel LocalArticle {\n  id            String   @id @default(cuid())\n  backendId     String   @unique // Backend article ID\n  title         String\n  visualTitle   String? // Clean title without publication\n  description   String\n  content       String? // Full article content\n  url           String\n  imageUrl      String?\n  publishedAt   DateTime\n  readTime      Int?\n  isTopHeadline Boolean  @default(false)\n\n  // Source information\n  sourceName    String\n  sourceLogoUrl String?\n\n  // Content metadata  \n  summary        String? // JSON summary object\n  richContent    String? // JSON rich content\n  contentStatus  String?\n  contentQuality String? // JSON quality metrics\n\n  // Topics and categorization\n  topics String? // JSON array of topic objects\n\n  // Local metadata\n  isRead  Boolean   @default(false)\n  isSaved Boolean   @default(false)\n  readAt  DateTime?\n  savedAt DateTime?\n\n  // Sync metadata\n  lastSyncAt DateTime @default(now())\n  createdAt  DateTime @default(now())\n  updatedAt  DateTime @updatedAt\n\n  // Relations\n  feedItems FeedItem[]\n\n  @@index([backendId])\n  @@index([publishedAt])\n  @@index([isTopHeadline])\n  @@index([isRead])\n  @@index([isSaved])\n}\n\n// Feed sync tracking and metadata\nmodel FeedSync {\n  id        String  @id @default(cuid())\n  userId    String\n  feedType  String // 'personalized', 'world'\n  topicSlug String? // null for 'for-you' or 'all'\n\n  // Sync status\n  lastSyncAt     DateTime\n  nextSyncAt     DateTime? // Scheduled next sync\n  isStale        Boolean   @default(false)\n  syncInProgress Boolean   @default(false)\n\n  // Pagination info from last sync\n  lastPage   Int     @default(1)\n  hasMore    Boolean @default(true)\n  totalItems Int?\n\n  // Sync metadata\n  syncCount         Int     @default(0)\n  lastSyncDuration  Int? // Milliseconds\n  lastError         String?\n  consecutiveErrors Int     @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  userProfile LocalUserProfile @relation(fields: [userId], references: [userId], onDelete: Cascade)\n  feedItems   FeedItem[]\n\n  @@unique([userId, feedType, topicSlug])\n  @@index([userId, feedType])\n  @@index([lastSyncAt])\n  @@index([nextSyncAt])\n  @@index([isStale])\n}\n\n// Join table for feed items (articles in feeds)\nmodel FeedItem {\n  id             String   @id @default(cuid())\n  feedSyncId     String\n  articleId      String\n  position       Int // Position in feed\n  relevanceScore Float? // For personalized feeds\n  addedAt        DateTime @default(now())\n\n  // Relations\n  feedSync FeedSync     @relation(fields: [feedSyncId], references: [id], onDelete: Cascade)\n  article  LocalArticle @relation(fields: [articleId], references: [id], onDelete: Cascade)\n\n  @@unique([feedSyncId, articleId])\n  @@index([feedSyncId, position])\n  @@index([articleId])\n}\n\n// Background sync job queue\nmodel SyncJob {\n  id        String  @id @default(cuid())\n  type      String // 'user_sync', 'feed_sync', 'article_detail'\n  userId    String?\n  feedType  String?\n  topicSlug String?\n  articleId String?\n\n  // Job status\n  status      String // 'pending', 'running', 'completed', 'failed'\n  priority    Int    @default(5) // 1-10, lower = higher priority\n  attempts    Int    @default(0)\n  maxAttempts Int    @default(3)\n\n  // Scheduling\n  scheduledAt DateTime\n  startedAt   DateTime?\n  completedAt DateTime?\n\n  // Results\n  result String? // JSON result data\n  error  String? // Error message if failed\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status, priority, scheduledAt])\n  @@index([type, userId])\n  @@index([scheduledAt])\n}\n",
